import json

def handle(method, path, data=None):
    db = {"users": {1: {"name": "Alice"}}}
    if method == "GET" and path == "/users/1":
        return 200, db["users"][1]
    if method == "POST" and path == "/users":
        db["users"][2] = data
        return 201, data
    return 404, {"error": "Not found"}

code, body = handle("GET", "/users/1")
print(code, json.dumps(body))
code2, body2 = handle("POST", "/users", {"name": "Bob"})
print(code2, json.dumps(body2))
